#!/usr/bin/env python3
# Generated by test-lab — blind adversarial evaluation
"""Test QuerySpec prompts with self-correction loop.

Tests both the trained GRPO model and a reference model (DeepSeek via API)
to compare output quality.
"""

import json
import os
import re
import sys
from pathlib import Path

import torch
from loguru import logger
from peft import AutoPeftModelForCausalLM
from transformers import AutoTokenizer

# Test cases
TEST_CASES = [
    {
        "id": "rf_jamming",
        "query": "How do I detect RF jamming attacks on satellite communications?",
        "expected_action": "QUERY",
        "expected_tier1": ["Detect"],
    },
    {
        "id": "weather_oos",
        "query": "What's the weather forecast for tomorrow?",
        "expected_action": "NO_MATCH",
    },
    {
        "id": "t1071",
        "query": "What controls mitigate T1071 application layer protocol attacks?",
        "expected_action": "QUERY",
        "expected_entities": ["T1071"],
    },
    {
        "id": "ambiguous",
        "query": "How do I make it more secure?",
        "expected_action": "CLARIFY",
    },
]

# Optimized prompt that suppresses CoT
QUERYSPEC_PROMPT = """You are a SPARTA QuerySpec generator. Convert user questions about space cybersecurity into structured JSON.

CRITICAL: Output ONLY valid JSON. No explanation, no reasoning, no text before or after the JSON.

Output this exact structure:
{
  "action": "QUERY" | "CLARIFY" | "NO_MATCH",
  "scope": "sparta",
  "lanes": ["bm25", "dense"],
  "entities": [],
  "tier0": [],
  "tier1": [],
  "keywords": [],
  "min_grounding": 0.7,
  "k": 12
}

Field Rules:
- action: "QUERY" for valid space/satellite cybersecurity questions
- action: "NO_MATCH" for out-of-scope (weather, recipes, general IT, non-space)
- action: "CLARIFY" for ambiguous questions needing more context
- entities: Extract MITRE ATT&CK IDs (T####), CWE IDs (CWE-###), or SPARTA control IDs (CM-####) if mentioned
- tier0: Conceptual tags from [Corruption, Fragility, Loyalty, Precision, Resilience, Stealth]
- tier1: Tactical tags from [Detect, Evade, Exploit, Harden, Isolate, Model, Persist, Restore]

Output ONLY the JSON. Nothing else."""


# Self-correction prompt
CORRECTION_PROMPT = """Your response was not valid JSON. Please output ONLY the JSON object.

Invalid output: {error}

Output ONLY this JSON structure with no other text:
{{"action": "QUERY"|"CLARIFY"|"NO_MATCH", "scope": "sparta", "lanes": [...], "entities": [...], "tier0": [...], "tier1": [...], "keywords": [...], "min_grounding": 0.7, "k": 12}}"""


def extract_json_from_response(text: str) -> dict | None:
    """Try to extract JSON from response, handling CoT noise."""
    # Try direct parse first
    text = text.strip()
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass

    # Look for JSON block in text
    patterns = [
        r'```json\s*([\s\S]*?)\s*```',  # Markdown JSON block
        r'```\s*([\s\S]*?)\s*```',       # Generic code block
        r'\{[^{}]*"action"[^{}]*\}',     # Simple JSON object with action
        r'\{[\s\S]*?\}(?=\s*$)',         # JSON at end of response
    ]

    for pattern in patterns:
        match = re.search(pattern, text)
        if match:
            try:
                json_str = match.group(1) if '```' in pattern else match.group(0)
                return json.loads(json_str)
            except (json.JSONDecodeError, IndexError):
                continue

    return None


def load_trained_model(model_path: str):
    """Load the GRPO-trained model."""
    logger.info(f"Loading trained model from {model_path}")

    model = AutoPeftModelForCausalLM.from_pretrained(
        model_path,
        torch_dtype=torch.bfloat16,
        device_map="auto",
        trust_remote_code=True,
    )
    tokenizer = AutoTokenizer.from_pretrained(model_path, trust_remote_code=True)

    return model, tokenizer


def generate_with_model(model, tokenizer, query: str, system_prompt: str) -> str:
    """Generate QuerySpec with the trained model."""
    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": query},
    ]

    text = tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
    inputs = tokenizer(text, return_tensors="pt").to(model.device)

    with torch.no_grad():
        outputs = model.generate(
            **inputs,
            max_new_tokens=256,
            temperature=0.3,
            do_sample=True,
            pad_token_id=tokenizer.eos_token_id,
        )

    response = tokenizer.decode(outputs[0][inputs["input_ids"].shape[1]:], skip_special_tokens=True)
    return response


def evaluate_response(response: str, expected: dict) -> dict:
    """Evaluate a response against expected values."""
    result = {"raw_response": response[:500], "json_parsed": False, "errors": []}

    parsed = extract_json_from_response(response)
    if not parsed:
        result["errors"].append("Failed to parse JSON from response")
        return result

    result["json_parsed"] = True
    result["parsed"] = parsed

    # Check action
    if "expected_action" in expected:
        if parsed.get("action") == expected["expected_action"]:
            result["action_correct"] = True
        else:
            result["action_correct"] = False
            result["errors"].append(f"Action mismatch: {parsed.get('action')} vs {expected['expected_action']}")

    # Check entities
    if "expected_entities" in expected:
        found_entities = set(parsed.get("entities", []))
        expected_entities = set(expected["expected_entities"])
        if expected_entities.issubset(found_entities):
            result["entities_correct"] = True
        else:
            result["entities_correct"] = False
            result["errors"].append(f"Entity mismatch: {found_entities} vs {expected_entities}")

    # Check tier1
    if "expected_tier1" in expected:
        found_tier1 = set(parsed.get("tier1", []))
        expected_tier1 = set(expected["expected_tier1"])
        if expected_tier1.intersection(found_tier1):
            result["tier1_correct"] = True
        else:
            result["tier1_correct"] = False
            result["errors"].append(f"Tier1 mismatch: {found_tier1} vs {expected_tier1}")

    return result


def main():
    model_path = Path(__file__).parent.parent / "outputs" / "grpo-intent-v1" / "attempt_1"

    if not model_path.exists():
        logger.error(f"Model path not found: {model_path}")
        sys.exit(1)

    logger.info("Loading model...")
    model, tokenizer = load_trained_model(str(model_path))

    logger.info("\n" + "="*60)
    logger.info("Testing QuerySpec generation with optimized prompt")
    logger.info("="*60)

    results = []
    for test in TEST_CASES:
        logger.info(f"\n--- Test: {test['id']} ---")
        logger.info(f"Query: {test['query']}")

        response = generate_with_model(model, tokenizer, test["query"], QUERYSPEC_PROMPT)
        logger.info(f"Raw response:\n{response[:500]}")

        eval_result = evaluate_response(response, test)
        eval_result["test_id"] = test["id"]
        results.append(eval_result)

        if eval_result["json_parsed"]:
            logger.success(f"Parsed JSON: {json.dumps(eval_result.get('parsed', {}), indent=2)[:300]}")
        else:
            logger.error("Failed to parse JSON")

        if eval_result.get("errors"):
            for err in eval_result["errors"]:
                logger.warning(f"  - {err}")

    # Summary
    logger.info("\n" + "="*60)
    logger.info("SUMMARY")
    logger.info("="*60)

    total = len(results)
    json_parsed = sum(1 for r in results if r["json_parsed"])
    action_correct = sum(1 for r in results if r.get("action_correct", False))

    logger.info(f"JSON Parse Rate: {json_parsed}/{total} ({100*json_parsed/total:.0f}%)")
    logger.info(f"Action Accuracy: {action_correct}/{total} ({100*action_correct/total:.0f}%)")

    # Save results
    output_path = model_path / "queryspec_prompt_test.json"
    with open(output_path, "w") as f:
        json.dump(results, f, indent=2)
    logger.info(f"Results saved to {output_path}")


if __name__ == "__main__":
    main()
